    91				}
    92				kevulns, err := client.driver.GetKEVulnByCveID(cveID)
    93				if err != nil {
    94					return err
    95				}
    96				if len(kevulns) == 0 {
    97					continue
    98				}
    99				data, err := json.Marshal(kevulns)
   100				if err != nil {
   101					return err
   102				}
   103				kevs, err := decodeKEVs(data)
   104				if err != nil {
   105					return err
   106				}
   107				if len(kevs) == 0 {
   108					continue
   109				}
   110				vuln.KEVs = append(vuln.KEVs, kevs...)
   111				nKEV++
   112				r.ScannedCves[cveID] = vuln
   113			}
   114		}
