    15	// decodeKEVs converts the KEV records returned by go-kev into the public
    16	// vulnerability model. Decoding through JSON keeps the mapping compatible
    17	// with feed records that add source-specific fields over time.
    18	func decodeKEVs(data []byte) ([]models.KEV, error) {
    19		var value json.RawMessage
    20		if err := json.Unmarshal(data, &value); err != nil {
    21			return nil, err
    22		}
    23		return decodeKEVValue(value, nil, ""), nil
    24	}
