    26	type kevRawFields map[string]json.RawMessage
    27	
    28	func decodeKEVValue(value json.RawMessage, inherited kevRawFields, forcedType models.KEVType) []models.KEV {
    29		value = bytes.TrimSpace(value)
    30		if len(value) == 0 || bytes.Equal(value, []byte("null")) {
    31			return nil
    32		}
    33	
    34		if value[0] == '[' {
    35			var values []json.RawMessage
    36			if json.Unmarshal(value, &values) != nil {
    37				return nil
    38			}
    39			var kevs []models.KEV
    40			for _, item := range values {
    41				kevs = append(kevs, decodeKEVValue(item, inherited, forcedType)...)
    42			}
    43			return kevs
    44		}
    45	
    46		var fields kevRawFields
    47		if err := json.Unmarshal(value, &fields); err != nil || fields == nil {
    48			return nil
    49		}
    50		fields = mergeKEVFields(inherited, fields)
    51	
    52		var sourced []models.KEV
    53		for _, source := range []struct {
    54			key      string
    55			typeName models.KEVType
    56		}{
    57			{key: "cisa", typeName: models.CISAKEVType},
    58			{key: "vulncheck", typeName: models.VulnCheckKEVType},
    59		} {
    60			if raw, ok := findKEVField(fields, source.key); ok {
    61				base := cloneKEVFields(fields)
    62				deleteKEVField(base, "cisa")
    63				deleteKEVField(base, "vulncheck")
    64				sourced = append(sourced, decodeKEVSource(raw, base, source.typeName)...)
    65			}
    66		}
    67		if len(sourced) > 0 {
    68			return sourced
    69		}
    70	
    71		if raw, ok := findKEVField(fields, "sources"); ok {
    72			base := cloneKEVFields(fields)
    73			deleteKEVField(base, "sources")
    74			if kevs := decodeKEVValue(raw, base, ""); len(kevs) > 0 {
    75				return kevs
    76			}
    77		}
    78	
    79		kev, ok := mapKEVFields(fields, forcedType)
    80		if !ok {
    81			return nil
    82		}
    83		return []models.KEV{kev}
    84	}
